if($username===''){http_response_code(400);$username='User PPPoE';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PPPoE User - <?=htmlspecialchars($username,ENT_QUOTES,'UTF-8')?> - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css?v=8"><link rel="stylesheet" href="../assets/css/common.css?v=8"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/pppoe.css?v=15"><style>body{margin:0}.user-page{max-width:1160px;margin:0 auto;padding:22px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.title{margin:0;color:var(--text);font-size:23px;font-weight:800}.sub{margin-top:4px;color:var(--muted);font-size:11px}.actions{display:flex;gap:7px;flex-wrap:wrap}.btnx{display:inline-flex;align-items:center;text-decoration:none;border:1px solid var(--border);background:var(--card);color:var(--text);border-radius:8px;padding:8px 12px;font-size:11px;font-weight:700}.btnx.primary{background:var(--primary);color:#fff;border-color:var(--primary)}.card{background:var(--card);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow-card,0 2px 10px rgba(0,0,0,.04));padding:15px;margin-bottom:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.info,.metric{border:1px solid var(--border);border-radius:10px;padding:11px}.info span,.metric span{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;margin-bottom:4px}.info b,.metric b{color:var(--text);font-size:14px;word-break:break-word}.metric b{font-size:17px}.live{display:inline-flex;align-items:center;gap:6px;font-size:10px;color:#059669;font-weight:700}.dot{width:7px;height:7px;border-radius:50%;background:#10b981}.offline{color:#dc3545}.traffic{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.chart-title{font-size:12px;font-weight:750;color:var(--text);margin-bottom:8px}.chart-wrap{height:280px}.chart{width:100%;height:100%;display:block}.note{color:var(--muted);font-size:9px;margin-top:8px}.error{color:#dc3545;font-size:10px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.section-head small{color:var(--muted);font-size:9px}.rangebar{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:9px}.range{border:1px solid var(--border);background:var(--card);color:var(--text);border-radius:7px;padding:6px 10px;font-size:10px;cursor:pointer}.range.active{background:var(--primary);border-color:var(--primary);color:#fff}@media(max-width:950px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.traffic{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.user-page{padding:12px}.head{align-items:flex-start;flex-direction:column}.grid,.traffic{grid-template-columns:1fr 1fr}.chart-wrap{height:230px}}@media(max-width:400px){.grid,.traffic{grid-template-columns:1fr}}
</style></head><body><main class="user-page"><header class="head"><div><h1 class="title">PPPoE User — <?=htmlspecialchars($username,ENT_QUOTES,'UTF-8')?></h1><div class="sub"><span id="status" class="live"><i class="dot"></i>Memuat status...</span><span id="updated"></span></div></div><div class="actions"><a class="btnx" href="./">← PPPoE</a><a class="btnx primary" href="history.php?username=<?=rawurlencode($username)?>">Traffic History</a></div></header><section class="card"><div class="grid"><div class="info"><span>Username</span><b id="name">-</b></div><div class="info"><span>IP Address</span><b id="ip">-</b></div><div class="info"><span>Profile</span><b id="profile">-</b></div><div class="info"><span>Service</span><b id="service">-</b></div><div class="info"><span>Caller ID / MAC</span><b id="caller">-</b></div><div class="info"><span>Interface</span><b id="iface">-</b></div><div class="info"><span>Uptime</span><b id="uptime">-</b></div><div class="info"><span>Session ID</span><b id="session">-</b></div></div></section><section class="card"><div class="section-head"><div class="chart-title">Live Traffic</div><small>Polling 10 detik</small></div><div class="traffic"><div class="metric"><b id="rx">0 B</b><span>RX TOTAL</span></div><div class="metric"><b id="tx">0 B</b><span>TX TOTAL</span></div><div class="metric"><b id="rxRate">0 B/s</b><span>DOWNLOAD LIVE</span></div><div class="metric"><b id="txRate">0 B/s</b><span>UPLOAD LIVE</span></div><div class="metric"><b id="avgRx">0 B/s</b><span>AVG DOWNLOAD</span></div><div class="metric"><b id="avgTx">0 B/s</b><span>AVG UPLOAD</span></div></div><div class="note">Kecepatan live dihitung dari perubahan counter antar polling.</div></section><section class="card"><div class="section-head"><div class="chart-title">Traffic History</div><small id="historyMeta">Memuat...</small></div><div class="rangebar"><button type="button" class="range" data-range="1h">1 Jam</button><button type="button" class="range" data-range="6h">6 Jam</button><button type="button" class="range active" data-range="24h">24 Jam</button><button type="button" class="range" data-range="7d">7 Hari</button><button type="button" class="range" data-range="30d">30 Hari</button></div><div class="chart-wrap"><canvas id="chart" class="chart"></canvas></div><div class="note" id="chartMsg"></div></section><section class="card"><div class="section-head"><div class="chart-title">Ringkasan Performa</div><small>Periode histori terpilih</small></div><div class="traffic"><div class="metric"><b id="peakRx">0 B/s</b><span>PEAK DOWNLOAD</span></div><div class="metric"><b id="peakTx">0 B/s</b><span>PEAK UPLOAD</span></div><div class="metric"><b id="historyRecords">0</b><span>RECORDS</span></div></div></section></main><script>const USER=<?=json_encode($username,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,statsApi='../api/pppoe_stats.php',histApi='../api/pppoe_history.php';const $=id=>document.getElementById(id);let oldRx=0,oldTx=0,oldAt=0,currentRange='24h';function bytes(n){n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';const u=['KB','MB','GB','TB'];let i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return n.toFixed(n>=100?0:1)+' '+u[i]}function rate(n){return bytes(n)+'/s'}function calcRates(d){const rx=(d.rx||[]).map(Number),tx=(d.tx||[]).map(Number),labels=d.labels||[],rr=[],tr=[];for(let i=0;i<rx.length;i++){if(i===0){rr.push(0);tr.push(0);continue}let t=(new Date('1970-01-01T'+labels[i]).getTime()-new Date('1970-01-01T'+labels[i-1]).getTime())/1000;if(t<=0||t>3600)t=10;rr.push(Math.max(0,rx[i]-rx[i-1])/t);tr.push(Math.max(0,tx[i]-tx[i-1])/t)}return{rx,tx,rr,tr}}function draw(d){const c=$('chart'),r=c.getBoundingClientRect(),q=devicePixelRatio||1,w=Math.max(320,r.width),h=Math.max(180,r.height);c.width=w*q;c.height=h*q;const x=c.getContext('2d');x.setTransform(q,0,0,q,0,0);x.clearRect(0,0,w,h);const z=calcRates(d),max=Math.max(...z.rr,...z.tr,1),L=52,R=18,T=16,B=30,pw=w-L-R,ph=h-T-B,s=getComputedStyle(document.body),mut=s.getPropertyValue('--muted')||'#64748b',bd=s.getPropertyValue('--border')||'#e2e8f0',pr=s.getPropertyValue('--primary')||'#2563eb';x.font='9px sans-serif';x.fillStyle=mut;x.strokeStyle=bd;for(let i=0;i<=4;i++){let y=T+ph*i/4;x.beginPath();x.moveTo(L,y);x.lineTo(L+pw,y);x.stroke();x.fillText(rate(max*(1-i/4)),3,y+3)}function line(a,dash){if(!a.length)return;x.beginPath();a.forEach((v,i)=>{let px=L+(a.length<2?0:pw*i/(a.length-1)),py=T+ph-(Number(v)/max)*ph;i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle=pr;x.lineWidth=2;x.setLineDash(dash?[5,4]:[]);x.stroke();x.setLineDash([])}line(z.rr,false);line(z.tr,true);x.fillStyle=mut;x.fillText('DOWNLOAD —',L,h-8);x.fillText('UPLOAD - -',L+75,h-8);if(d.labels?.length){x.fillText(d.labels[0],L,h-19);x.fillText(d.labels[d.labels.length-1],Math.max(L,w-95),h-19)}}async function refresh(){try{const r=await fetch(statsApi+'?t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Gagal mengambil status');const u=(d.active||[]).find(x=>String(x.name).toLowerCase()===USER.toLowerCase());if(!u){$('status').innerHTML='<i class="dot" style="background:#dc3545"></i> OFFLINE';$('status').classList.add('offline');return}$('status').innerHTML='<i class="dot"></i> ONLINE';$('status').classList.remove('offline');$('name').textContent=u.name||USER;$('ip').textContent=u.address||'-';$('profile').textContent=u.profile||'-';$('service').textContent=u.service||'-';$('caller').textContent=u.caller_id||'-';$('iface').textContent=u.interface||'-';$('uptime').textContent=u.uptime||'-';$('session').textContent=u.session_id||'-';$('rx').textContent=bytes(u.bytes_in);$('tx').textContent=bytes(u.bytes_out);const now=Date.now(),dt=oldAt?(now-oldAt)/1000:0,rr=dt>0?Math.max(0,(Number(u.bytes_in)||0)-oldRx)/dt:0,tr=dt>0?Math.max(0,(Number(u.bytes_out)||0)-oldTx)/dt:0;$('rxRate').textContent=rate(rr);$('txRate').textContent=rate(tr);oldRx=Number(u.bytes_in)||0;oldTx=Number(u.bytes_out)||0;oldAt=now;$('updated').textContent=' • '+new Date().toLocaleTimeString('id-ID')}catch(e){$('status').textContent=e.message}}async function history(){try{const r=await fetch(histApi+'?username='+encodeURIComponent(USER)+'&range='+currentRange+'&t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'History gagal');const z=calcRates(d),ar=z.rr.filter(v=>v>0),at=z.tr.filter(v=>v>0);$('historyMeta').textContent=(d.records||0)+' records';$('avgRx').textContent=rate(ar.length?ar.reduce((a,b)=>a+b,0)/ar.length:0);$('avgTx').textContent=rate(at.length?at.reduce((a,b)=>a+b,0)/at.length:0);$('peakRx').textContent=rate(ar.length?Math.max(...ar):0);$('peakTx').textContent=rate(at.length?Math.max(...at):0);$('historyRecords').textContent=d.records||0;draw(d)}catch(e){$('chartMsg').textContent=e.message;draw({})}}document.querySelectorAll('.range').forEach(b=>b.addEventListener('click',()=>{currentRange=b.dataset.range;document.querySelectorAll('.range').forEach(x=>x.classList.toggle('active',x===b));history()}));refresh();history();setInterval(refresh,10000);setInterval(history,10000);</script></body></html>